padlocks.code:
/**
 * Padlocks: five padlocks hung on a rail, each a rounded body with a keyhole
 * under a U-shaped shackle. The pointer picks a lock: its shackle springs up
 * open, and the shackles beside it lift a little, staggered from it. At rest
 * one lock hangs open, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the pick is the lock
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, fit, facing, open, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, place, pointer, put, register, solid,
} = HL;

const N = 5, BW = 20, BD = 12, BH = 22, GAP = 12, SR = 6, LEG = 9, OPEN = 11, FAV = 2;
const X1 = N * BW + (N - 1) * GAP, RAIL = BH + LEG + SR + 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-8, 0, 0], [X1 + 8, BD, 0], [X1 + 8, 0, 0], [-8, BD, 0], [-8, BD / 2, RAIL + 4], [X1 + 8, BD / 2, RAIL + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the rail the locks hang from: a bar on two posts
  const [pr, pi] = rings(-8, BD / 2 - 2, -4, BD / 2 + 2, 1, 0.5);
  put(solid(g), prism(P, front, pr, pi, 0, RAIL + 3));
  const [rr, ri] = rings(-8, BD / 2 - 1.6, X1 + 8, BD / 2 + 1.6, 1.4, 0.5);
  const rail = solid(g);

  const locks = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * (BW + GAP), cx = x0 + BW / 2;
    const shackle = mk("path", { class: "nf sil" }, g);
    const body = solid(g), hole = mk("path", { class: "nf" }, body.g);
    const [r, i] = rings(x0, 0, x0 + BW, BD, 3.5, 1.4);
    put(body, prism(P, front, r, i, 0, BH));
    const kz = BH * 0.45;
    hole.setAttribute("d", seg(P(cx, BD, kz - 1), P(cx, BD, kz - 5)));
    place(mk("circle", { r: 1.6, class: "dot m" }, body.g), P(cx, BD, kz));
    locks.push({ k, cx, shackle, body, z: tween(k === FAV ? OPEN : 0), last: NaN });
  }
  put(rail, prism(P, front, rr, ri, RAIL, RAIL + 3));
  const [qr, qi] = rings(X1 + 4, BD / 2 - 2, X1 + 8, BD / 2 + 2, 1, 0.5);
  put(solid(g), prism(P, front, qr, qi, 0, RAIL + 3));

  /** The shackle lifted z: two legs and the arch, in the lock's middle plane; open, the left leg clears the body. */
  function draw(l, z) {
    if (z === l.last) return;
    l.last = z;
    const y = BD / 2, base = BH + z, top = base + LEG, arc = [];
    for (let i = 0; i <= 12; i++) { const t = Math.PI - (Math.PI * i) / 12; arc.push(P(l.cx + SR * Math.cos(t), y, top + SR * Math.sin(t))); }
    const leftFoot = z > 0.5 ? base + Math.min(z, 5) : BH - 1;
    l.shackle.setAttribute("d", open([P(l.cx - SR, y, leftFoot), ...arc, P(l.cx + SR, y, BH - 1)]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const l of locks) { draw(l, tval(l.z, now)); if (!tdone(l.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = locks.map((l) => P(l.cx, BD, BH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 20 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    locks.forEach((l, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? OPEN : 0) : dd === 0 ? OPEN : dd === 1 ? 3 : 0;
      tset(l.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      l.shackle.setAttribute("class", on ? "nf hi" : "nf sil");
      l.body.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "lock " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "padlocks",
  means: "Five padlocks on a rail: the shackle of the one under the pointer springs open, and its neighbours lift a little.",
  rules: [1, 2, 5, 10],
  range: [0, 45, 90],
  tour: [[115, 150], [233, 206], [272, 224], null],
  mount,
});

cropfield.code:
/**
 * Crop field: four raised beds of soil, each with a row of six seedlings, a
 * stem and two leaves apiece. The pointer is the sun and the rain: the plants
 * near it grow tall and open their leaves, the farther the less, each on its
 * own spring. At rest the field is young, a little taller toward the back.
 * The slider is the reach, in plants.
 *
 * The pattern: a continuous field (terrain), on plants; the hit is on the
 * ground plane, which never moves.
 */
const {
  Cam, clamp, facing, fit, open, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NX = 6, NY = 4, SX = 18, SY = 24, BEDW = 12, BEDH = 5, HMAX = 34;
const EX = NX * SX, EY = NY * SY;
const falloff = (u) => (u <= 0.4 ? 1 : u <= 1 ? 1 - ((u - 0.4) / 0.6) * 0.78 : 0.22);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value * SX, over = null;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-6, -6, -3], [EX + 6, EY + 6, -3], [EX + 6, -6, -3], [-6, EY + 6, -3], [0, 0, BEDH + HMAX + 6]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [gr, gi] = rings(-6, -6, EX + 6, EY + 6, 8, 2);
  put(solid(g), prism(P, front, gr, gi, -3, 0));

  const plants = [];
  for (let j = 0; j < NY; j++) {
    // the bed for row j, then its plants back to front
    const y0 = j * SY + (SY - BEDW) / 2;
    const [br, bi] = rings(2, y0, EX - 2, y0 + BEDW, 4, 1.4);
    put(solid(g), prism(P, front, br, bi, 0, BEDH));
    for (let i = 0; i < NX; i++) {
      const cx = (i + 0.5) * SX, cy = j * SY + SY / 2;
      const h0 = 7 + (NY - 1 - j) * 2.5 + ((i * 5 + j * 3) % 4);
      const stem = mk("path", { class: "nf sil" }, g), leaves = mk("path", { class: "nf" }, g);
      plants.push({ i, j, cx, cy, h0, stem, leaves, sp: spring(h0, { eps: 0.04 }), drawn: NaN });
    }
  }

  /** A seedling h tall: a stem, and two leaves that open wider as it grows. */
  function draw(p) {
    const h = Math.max(3, p.sp.x);
    if (h === p.drawn) return;
    p.drawn = h;
    const z0 = BEDH, top = z0 + h, s = clamp(h / HMAX, 0.25, 1), L = 6 + 9 * s;
    p.stem.setAttribute("d", open([P(p.cx, p.cy, z0), P(p.cx + 0.6, p.cy, z0 + h * 0.5), P(p.cx, p.cy, top)]));
    const zl = top - h * 0.35, leaf = (dx, dz) => open([P(p.cx, p.cy, zl), P(p.cx + dx * 0.45, p.cy, zl + dz + 3.5), P(p.cx + dx, p.cy, zl + dz), P(p.cx + dx * 0.5, p.cy, zl + dz - 2.2), P(p.cx, p.cy, zl)]);
    p.leaves.setAttribute("d", leaf(-L, 2 + 4 * s) + leaf(L, 1 + 4 * s));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const p of plants) { if (stepS(p.sp, dt)) m = true; draw(p); }
    return m;
  });
  bag.add(B.unregister);

  const tallest = plants.reduce((a, b) => (b.h0 > a.h0 ? b : a));
  function retarget() {
    let mark = tallest;
    for (const p of plants) p.sp.t = over ? HMAX * falloff(Math.hypot(p.cx - over[0], p.cy - over[1]) / RAD) : p.h0;
    if (over) {
      const i = clamp(Math.floor(over[0] / SX), 0, NX - 1), j = clamp(Math.floor(over[1] / SY), 0, NY - 1);
      mark = plants.find((p) => p.i === i && p.j === j);
      read.textContent = `row ${j + 1}·${i + 1}`;
    } else read.textContent = "rest";
    for (const p of plants) { p.stem.setAttribute("class", p === mark ? "nf hi" : "nf sil"); }
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (pt) => { const q = unproj(C, pt[0], pt[1], BEDH); over = [clamp(q[0], 0, EX), clamp(q[1], 0, EY)]; retarget(); },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v * SX; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "cropfield",
  means: "Four beds of seedlings: the plants near the pointer grow tall and open their leaves, the farther ones less.",
  rules: [1, 3, 5, 8],
  range: [1.5, 2.5, 4],
  tour: [[150, 190], [250, 170], [210, 235], null],
  mount,
});

dumbbells.code:
/**
 * Dumbbells: six dumbbells resting across a rack, light to heavy, each two
 * round plates on a short grip. The pointer picks one by where it rests: it
 * lifts off the rack, and the ones beside it rise a little, staggered from
 * it. At rest the heaviest pair is lifted, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = [4.5, 5, 5.6, 6.2, 6.8, 7.6], PT = 3.6, GRIP = 9, STEP = 19, RACK = 16, LIFT = 18, FAV = 5;
const X1 = (R.length - 1) * STEP + 20, YL = PT * 2 + GRIP;

/** A round plate with its axis along y, from y0 to y1, centred at (x, z): its outline and its front face. */
function plate(P, x, z, r, y0, y1) {
  const ring = (y) => Array.from({ length: 28 }, (_, i) => { const t = (i / 28) * Math.PI * 2; return P(x + r * Math.cos(t), y, z + r * Math.sin(t)); });
  return { sil: poly(hull(ring(y0).concat(ring(y1)))), face: poly(ring(y1)) };
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-6, -6, 0], [X1 + 6, YL + 8, 0], [X1 + 6, -6, 0], [-6, YL + 8, 0], [0, 0, RACK + 8 + LIFT + 2], [X1, 0, RACK + 8 + LIFT + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the rack: a board on two feet
  for (const x0 of [2, X1 - 8]) { const [r, i] = rings(x0, -2, x0 + 6, YL + 4, 1.2, 0.6); put(solid(g), prism(P, front, r, i, 0, RACK - 3)); }
  const [br, bi] = rings(-4, -4, X1 + 4, YL + 6, 2.5, 1.2);
  put(solid(g), prism(P, front, br, bi, RACK - 3, RACK));

  const bells = R.map((r, k) => {
    const x = 10 + k * STEP, grp = mk("g", {}, g);
    const back = mk("path", { class: "sil" }, grp), backFace = mk("path", { class: "nf lo" }, grp);
    const grip = mk("path", { class: "nf sil" }, grp);
    const frontP = mk("path", { class: "sil" }, grp), frontFace = mk("path", { class: "nf lo" }, grp);
    return { k, x, r, grp, back, backFace, grip, frontP, frontFace, z: tween(k === FAV ? LIFT * 0.75 : 0), last: NaN };
  });

  function draw(b, lift) {
    if (lift === b.last) return;
    b.last = lift;
    const z = RACK + b.r + lift, y0 = 1, y1 = y0 + PT, y2 = y1 + GRIP, y3 = y2 + PT;
    const a = plate(P, b.x, z, b.r, y0, y1), c = plate(P, b.x, z, b.r, y2, y3);
    b.back.setAttribute("d", a.sil); b.backFace.setAttribute("d", a.face);
    b.grip.setAttribute("d", seg(P(b.x, y1, z + 1.3), P(b.x, y2, z + 1.3)) + seg(P(b.x, y1, z - 1.3), P(b.x, y2, z - 1.3)));
    b.frontP.setAttribute("d", c.sil); b.frontFace.setAttribute("d", c.face);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const b of bells) { draw(b, tval(b.z, now)); if (!tdone(b.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = bells.map((b) => P(b.x, YL / 2, RACK + b.r));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 16 && Math.abs(mids[best][1] - sy) < 55 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    bells.forEach((b, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.75 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(b.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      b.back.classList.toggle("hi", on); b.frontP.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "dumbbell " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "dumbbells",
  means: "Six dumbbells on a rack, light to heavy: the one under the pointer lifts off, and its neighbours rise a little.",
  rules: [1, 2, 5, 9],
  range: [0, 45, 90],
  tour: [[122, 121], [185, 152], [282, 196], null],
  mount,
});

swatchfan.code:
/**
 * Swatch fan: nine colour cards fanned out from a pin, each card ruled into
 * three swatches, a hole at its foot. The pointer picks the card pointing its
 * way: it slides out along its length and lifts, and the cards beside it lean
 * away, staggered from it. At rest the fan is open with one card drawn out,
 * bright. The slider is the stagger.
 *
 * The pattern: one of many round a pivot (riffle). The pick is the card whose
 * resting angle is nearest the pointer's angle about the pin.
 */
const {
  Cam, circ, clamp, fit, facing, fillet, poly, prism, proj, rad, rings, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 9, L = 78, W = 15, TK = 0.9, A0 = -18, SPREAD = 8, OUT = 12, LEAN = 4, FAV = 5;
const restA = (k) => A0 + k * SPREAD;
const SHAPE = fillet([[0, -W / 2], [L, -W / 2], [L, W / 2], [0, W / 2]], [W / 2, 2.5, 2.5, W / 2]);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.2);
  const ext = [];
  // every card's far corners at its widest lean and furthest slide, the stack's top and foot, and the pin
  for (let a = A0 - LEAN; a <= restA(N - 1) + LEAN; a += 4) for (const v of [-W / 2, W / 2]) for (const z of [0, N * 1.2 + 6]) {
    const u = L + OUT; ext.push([u * Math.cos(rad(a)) - v * Math.sin(rad(a)), u * Math.sin(rad(a)) + v * Math.cos(rad(a)), z]);
  }
  fit(C, [...ext, [-W / 2, -W / 2, 0], [W / 2, W / 2, N * 1.2 + 3]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const cards = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    const edge = mk("path", { class: "lo" }, grp), face = mk("path", { class: "sil" }, grp), lines = mk("path", { class: "nf lo" }, grp);
    cards.push({ k, grp, edge, face, lines, a: tween(restA(k)), s: tween(k === FAV ? OUT * 0.7 : 0), last: "" });
  }
  // the pin through every card's foot, over the stack
  const pin = solid(g);
  { const ring = circ(3.2, 24), inner = circ(2, 24); put(pin, prism(P, front, ring, inner, 0, N * 1.2 + 3)); }

  function draw(c, a, s) {
    const key = a.toFixed(2) + "," + s.toFixed(2);
    if (key === c.last) return;
    c.last = key;
    const ca = Math.cos(rad(a)), sa = Math.sin(rad(a)), z = 1 + c.k * 1.2 + (s > 0.1 ? s * 0.3 : 0);
    const w = (u, v, zz = z) => P((u + s) * ca - v * sa, (u + s) * sa + v * ca, zz);
    c.face.setAttribute("d", poly(SHAPE.map(([u, v]) => w(u, v))));
    c.edge.setAttribute("d", poly(SHAPE.map(([u, v]) => w(u, v, z - TK))));
    let d = "";
    for (const u of [L * 0.4, L * 0.6, L * 0.8]) d += seg(w(u, -W / 2 + 1.2), w(u, W / 2 - 1.2));
    c.lines.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const c of cards) { draw(c, tval(c.a, now), tval(c.s, now)); if (!tdone(c.a, now) || !tdone(c.s, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  /** The card whose resting angle is nearest the pointer's angle about the pin, on the ground plane. */
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, N * 0.6), r = Math.hypot(x, y);
    if (r < 10 || r > L + OUT + 8) return -1;
    const ang = (Math.atan2(y, x) * 180) / Math.PI;
    if (ang < A0 - SPREAD || ang > restA(N - 1) + SPREAD) return -1;
    return clamp(Math.round((ang - A0) / SPREAD), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    cards.forEach((c, k) => {
      const delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(c.a, a < 0 ? restA(k) : restA(k) + (k < a ? -LEAN : k > a ? LEAN : 0), now, delay);
      tset(c.s, a < 0 ? (k === FAV ? OUT * 0.7 : 0) : k === a ? OUT : 0, now, delay);
      c.face.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "card " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "swatchfan",
  means: "A fan of nine colour cards: the card pointing toward the pointer slides out, and the cards beside it lean away.",
  rules: [1, 2, 5, 10],
  range: [0, 40, 80],
  tour: [[243, 143], [187, 169], [110, 183], null],
  mount,
});

spotlights.code:
/**
 * Spotlights: four stage lamps hung from a truss over a round stage, each a
 * flared can on a yoke. The pointer is where the light should fall: every
 * lamp turns to aim at it, the spot on the stage follows on a spring, and the
 * lamp nearest it is bright. At rest the lamps meet on a spot left of centre.
 * The slider is how quickly the lamps follow (a stiffer or softer spring).
 *
 * The pattern: a continuous aim (terrain's spring, on an angle); the hit is on
 * the stage's plane, which never moves.
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const RS = 62, TRUSS = 92, HANG = 12, XS = [-48, -16, 16, 48], LEN = 18, RB = 5, RF = 7.5;
const REST = [-14, 10];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[-RS, -RS, -6], [RS, RS, -6], [RS, -RS, -6], [-RS, RS, -6], [-58, 0, TRUSS + 4], [58, 0, TRUSS + 4]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(RS, 72), circ(RS - 2, 72), -6, 0));
  const spotEl = mk("path", { class: "nf hi" }, g);
  // the truss: one bar along x, and the lamps under it, far to near
  const [tr, ti] = rings(-58, -2.5, 58, 2.5, 1.5, 0.6);
  put(solid(g), prism(P, front, tr, ti, TRUSS, TRUSS + 5));
  const lamps = XS.map((x, k) => {
    const yoke = mk("path", { class: "nf sil" }, g), body = mk("path", { class: "sil" }, g), lens = mk("path", { class: "nf" }, g);
    return { k, c: [x, 0, TRUSS - HANG], yoke, body, lens };
  });
  const tx = spring(REST[0], { k: 100 * value, c: 18 * Math.sqrt(value) }), ty = spring(REST[1], { k: 100 * value, c: 18 * Math.sqrt(value) });
  let lastKey = "", over = null;

  /** A can from back (radius RB) to a flared front (RF), along d from its middle. */
  function can(l, d) {
    const [cx, cy, cz] = l.c, z = [0, 0, 1];
    let u = [d[1] * z[2] - d[2] * z[1], d[2] * z[0] - d[0] * z[2], d[0] * z[1] - d[1] * z[0]];
    const un = Math.hypot(...u) || 1; u = u.map((x) => x / un);
    const v = [u[1] * d[2] - u[2] * d[1], u[2] * d[0] - u[0] * d[2], u[0] * d[1] - u[1] * d[0]];
    const ring = (off, r) => Array.from({ length: 24 }, (_, i) => {
      const t = (i / 24) * Math.PI * 2, q = (j) => [cx, cy, cz][j] + d[j] * off + r * (Math.cos(t) * u[j] + Math.sin(t) * v[j]);
      return P(q(0), q(1), q(2));
    });
    const back = ring(-LEN / 2, RB), lensRing = ring(LEN / 2, RF);
    l.body.setAttribute("d", poly(hull(back.concat(lensRing))));
    l.lens.setAttribute("d", poly(lensRing));
    l.yoke.setAttribute("d", seg(P(cx, cy, TRUSS), P(cx, cy, cz + RB)));
  }

  function draw() {
    const key = tx.x.toFixed(2) + "," + ty.x.toFixed(2);
    if (key === lastKey) return;
    lastKey = key;
    for (const l of lamps) {
      const d = [tx.x - l.c[0], ty.x - l.c[1], 0 - l.c[2]], n = Math.hypot(...d);
      can(l, d.map((x) => x / n));
    }
    const ring = circ(9, 40).map((q) => P(tx.x + q.u, ty.x + q.v, 0.2));
    spotEl.setAttribute("d", poly(ring));
  }

  const B = register(stage, (dt) => { const a = stepS(tx, dt), b = stepS(ty, dt); draw(); return a || b; });
  bag.add(B.unregister);

  function retarget() {
    const [x, y] = over ?? REST;
    tx.t = x; ty.t = y;
    let near = -1;
    if (over) { let bd = Infinity; lamps.forEach((l, k) => { const dd = Math.abs(l.c[0] - x); if (dd < bd) { bd = dd; near = k; } }); }
    lamps.forEach((l, k) => l.body.classList.toggle("hi", k === near));
    read.textContent = over ? `lamp ${near + 1} · ${Math.round(Math.hypot(x, y))}` : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y), k = Math.min(1, (RS - 10) / r);
      over = r > RS + 30 ? null : [x * k, y * k];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { tx.k = ty.k = 100 * v; tx.c = ty.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "spotlights",
  means: "Four stage lamps on a truss: they turn to aim where the pointer is, and the spot follows across the stage.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[140, 230], [260, 230], [200, 260], null],
  mount,
});

testtubes.code:
/**
 * Test tubes: six glass tubes standing in a two-deck rack, each with a
 * rounded foot, a lip at the mouth and liquid filled to its own level. The
 * pointer picks a tube by where it stands: it lifts out of the rack, and the
 * tubes beside it rise a little, staggered from it. At rest one tube stands
 * raised, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, STEP = 15, R = 4.6, TL = 52, DECK = 26, RW = 12, LIFT = 22, FAV = 2;
const LEVEL = [0.55, 0.35, 0.7, 0.45, 0.6, 0.3];
const X1 = (N - 1) * STEP + 16;
const ringAtXY = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-6, -6, 0], [X1 + 6, RW + 6, 0], [X1 + 6, -6, 0], [-6, RW + 6, 0], [0, RW / 2, TL + LIFT + 4], [X1, RW / 2, TL + LIFT + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the rack: a base, two end posts and the upper deck with a hole per tube
  const [br, bi] = rings(-6, -2, X1 + 6, RW + 2, 2.5, 1.2);
  put(solid(g), prism(P, front, br, bi, 0, 3));
  for (const x0 of [-6, X1 + 2]) { const [r, i] = rings(x0, 0, x0 + 4, RW, 1, 0.5); put(solid(g), prism(P, front, r, i, 3, DECK)); }

  const tubes = [];
  for (let k = 0; k < N; k++) {
    const x = 8 + k * STEP, y = RW / 2, grp = mk("g", {}, g);
    const glass = mk("path", { class: "sil" }, grp), liquid = mk("path", { class: "nf lo" }, grp), lip = mk("path", { class: "nf" }, grp);
    tubes.push({ k, x, y, grp, glass, liquid, lip, z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN });
  }
  const deck = solid(g);
  const [dr, di] = rings(-6, -1, X1 + 6, RW + 1, 2, 1);
  put(deck, prism(P, front, dr, di, DECK, DECK + 3));
  const holes = mk("path", { class: "nf lo" }, deck.g);
  holes.setAttribute("d", tubes.map((t) => poly(ringAt(P, ringAtXY(t.x, t.y, R + 0.8), DECK + 3))).join(""));
  // tubes rise through the deck: the part above it is drawn again after the deck
  const tops = tubes.map((t) => { const grp = mk("g", {}, g); return { grp, glass: mk("path", { class: "sil" }, grp), liquid: mk("path", { class: "nf lo" }, grp), lip: mk("path", { class: "nf" }, grp) }; });

  function shape(t, lift, from) {
    const z0 = 3 + lift, z1 = z0 + TL, foot = [];
    for (let i = 0; i <= 10; i++) { const a = Math.PI + (Math.PI * i) / 10; foot.push(P(t.x + R * Math.cos(a), t.y + R * Math.sin(a) * 0.0, z0 + R + R * Math.sin(a))); }
    const ring = ringAtXY(t.x, t.y, R), lo = Math.max(z0 + R, from);
    const pts = ringAt(P, ring, z1).concat(ringAt(P, ring, lo)).concat(lo <= z0 + R ? ringAt(P, ringAtXY(t.x, t.y, R * 0.55), z0 + 0.8) : []);
    const lvl = z0 + R + (TL - R - 6) * LEVEL[t.k];
    return {
      glass: poly(hull(pts)),
      liquid: lvl > from ? open(ringAt(P, run(ring, front), lvl)) : "",
      lip: poly(ringAt(P, ringAtXY(t.x, t.y, R + 1), z1)),
    };
  }

  function draw(t, i, lift) {
    if (lift === t.last) return;
    t.last = lift;
    const a = shape(t, lift, 0), b = shape(t, lift, DECK + 3);
    t.glass.setAttribute("d", a.glass); t.liquid.setAttribute("d", a.liquid); t.lip.setAttribute("d", "");
    const top = tops[i];
    top.glass.setAttribute("d", b.glass); top.liquid.setAttribute("d", b.liquid); top.lip.setAttribute("d", b.lip);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    tubes.forEach((t, i) => { draw(t, i, tval(t.z, now)); if (!tdone(t.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  const mids = tubes.map((t) => P(t.x, t.y, TL * 0.6));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 12 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    tubes.forEach((t, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 6 : 0;
      tset(t.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      tops[k].glass.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "tube " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "testtubes",
  means: "Six test tubes in a rack: the one under the pointer lifts out, and the tubes beside it rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[135, 124], [213, 163], [265, 189], null],
  mount,
});

brickwall.code:
/**
 * Brick wall: a garden wall of thirty bricks in running bond on a footing,
 * with a coping course on top. The pointer presses on the wall's face: the
 * bricks near it push out toward the reader, the farther the less, each on
 * its own spring. At rest a few bricks stand proud near one corner, as if
 * the wall were half built. The slider is the reach, in bricks.
 *
 * The pattern: a continuous field on a face (terrain, turned upright); the hit
 * is read on the wall's face plane, which never moves.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const COLS = 6, ROWS = 5, BW = 20, BH = 8, D = 10, J = 0.9, OUT = 9, FOOT = 4;
const W = COLS * BW, H = FOOT + ROWS * BH;
const fall = (u) => (u <= 0.35 ? 1 : u <= 1 ? 1 - ((u - 0.35) / 0.65) * 0.9 : 0.1);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value, over = null;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-4, -2, 0], [W + 4, D + OUT + 2, 0], [W + 4, -2, 0], [-4, D + OUT, 0], [-4, 0, H + 6], [W + 4, 0, H + 6]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [fr, fi] = rings(-4, -2, W + 4, D + 3, 1.5, 0.8);
  put(solid(g), prism(P, front, fr, fi, 0, FOOT));

  const bricks = [];
  for (let r = 0; r < ROWS; r++) {
    const off = r % 2 ? -BW / 2 : 0;
    for (let c = 0; c <= COLS; c++) {
      let x0 = c * BW + off, x1 = x0 + BW;
      x0 = Math.max(0, x0); x1 = Math.min(W, x1);
      if (x1 - x0 < 4) continue;
      const z0 = FOOT + r * BH, cx = (x0 + x1) / 2, cz = z0 + BH / 2;
      const rest = Math.max(0, 6 - Math.hypot((cx - W * 0.85) / BW, (cz - H * 0.8) / BH) * 2.4);
      bricks.push({ r, x0, x1, z0, cx, cz, rest, el: solid(g), sp: spring(rest, { eps: 0.03 }), drawn: NaN });
    }
  }
  const coping = solid(g);
  { const [r, i] = rings(-2, -1.5, W + 2, D + 1.5, 1.2, 0.7); put(coping, prism(P, front, r, i, H + 0.4, H + 3.6)); }

  // proud bricks paint after flush ones; within a course, left to right
  let painted = "";
  function order() {
    const o = bricks.slice().sort((a, b) => a.sp.x - b.sp.x || a.cx + a.cz * 0.01 - (b.cx + b.cz * 0.01));
    const key = o.map((b) => bricks.indexOf(b)).join();
    if (key !== painted) { painted = key; for (const b of o) g.appendChild(b.el.g); g.appendChild(coping.g); }
  }
  function draw(b) {
    const s = Math.max(0, b.sp.x);
    if (s === b.drawn) return;
    b.drawn = s;
    const [r, i] = rings(b.x0 + J / 2, s, b.x1 - J / 2, D + s, 1, 0.5);
    put(b.el, prism(P, front, r, i, b.z0 + J / 2, b.z0 + BH - J / 2));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const b of bricks) { if (stepS(b.sp, dt)) m = true; draw(b); }
    order();
    return m;
  });
  bag.add(B.unregister);

  /** Where the point lands on the wall's face (y = D), which never moves; null off the wall. */
  function onFace([sx, sy]) {
    const c = Math.cos(C.az), s = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
    const x = ((sx - C.ox) / C.S + D * s) / c, Y = x * s + D * c, z = (Y * C.k - (sy - C.oy) / C.S) / zf;
    return x < -6 || x > W + 6 || z < FOOT - 4 || z > H + 6 ? null : [x, z];
  }

  const restMark = bricks.reduce((a, b) => (b.rest > a.rest ? b : a));
  function retarget() {
    let mark = restMark;
    for (const b of bricks) b.sp.t = over ? OUT * fall(Math.hypot((b.cx - over[0]) / BW, (b.cz - over[1]) / BH) / reach) : b.rest;
    if (over) {
      mark = bricks.reduce((a, b) => (Math.hypot(b.cx - over[0], (b.cz - over[1]) * 2) < Math.hypot(a.cx - over[0], (a.cz - over[1]) * 2) ? b : a));
      read.textContent = `brick ${ROWS - mark.r}·${clamp(Math.floor(mark.cx / BW) + 1, 1, COLS + 1)}`;
    } else read.textContent = "rest";
    for (const b of bricks) b.el.sil.classList.toggle("hi", b === mark);
    B.wake();
  }

  bag.add(pointer(stage, { move: (p) => { over = onFace(p); retarget(); }, leave: () => { over = null; retarget(); } }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { reach = v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "brickwall",
  means: "A brick wall: the bricks near the pointer push out toward you, the nearest furthest.",
  rules: [1, 3, 5, 6],
  range: [1, 1.8, 3],
  tour: [[140, 150], [210, 200], [260, 190], null],
  mount,
});

wrenches.code:
/**
 * Wrenches: a fitted tray of six spanners lying in size order, each a flat
 * handle with an open jaw at one end and a ring at the other. The pointer
 * picks a spanner by where it lies: it lifts out of the tray, and the ones
 * beside it rise a little, staggered from it. At rest one spanner is lifted,
 * bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), lying flat.
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const SIZES = [0.72, 0.8, 0.88, 0.96, 1.04, 1.12], GAP = 15, LEN = 74, TK = 1.6, LIFT = 14, FAV = 3;
const X1 = SIZES.length * GAP + 10;

/** A spanner's outline in its own plane (u along it, v across), scale s: an open jaw, a waisted handle, a ring. */
function outline(s) {
  const pts = [], jaw = 7 * s, ring = 6 * s, hw = 2.6 * s, L = LEN * (0.8 + 0.2 * s);
  // open jaw at u = 0: an arc with a notch
  for (let i = 0; i <= 10; i++) { const a = Math.PI * 0.55 + (Math.PI * 1.45 * i) / 10; pts.push([jaw * Math.cos(a), jaw * Math.sin(a)]); }
  pts.push([jaw * 0.2, -jaw * 0.35], [jaw * 0.2, jaw * 0.35]);
  const jawPts = pts.splice(0);
  const out = [];
  out.push([jaw * 0.6, hw], [L - ring * 1.1, hw]);
  for (let i = 0; i <= 14; i++) { const a = Math.PI * 0.75 - (Math.PI * 1.5 * i) / 14; out.push([L + ring * Math.cos(a), ring * Math.sin(a)]); }
  out.push([L - ring * 1.1, -hw], [jaw * 0.6, -hw]);
  // join: handle top edge, ring, handle bottom edge, then the jaw back round to the start
  return out.concat(jawPts.slice(0, 6).reverse().map(([u, v]) => [u, -Math.abs(v)]), [[jaw * 0.2, -jaw * 0.35], [jaw * 0.2, jaw * 0.35]], jawPts.slice(6).map(([u, v]) => [u, Math.abs(v)]));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-6, -14, -4], [LEN + 20, X1, -4], [LEN + 20, -14, -4], [-6, X1, -4], [LEN / 2, 0, LIFT + 4]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(-12, -14, LEN + 22, X1, 6, 2);
  put(solid(g), prism(P, front, tr, ti, -4, 0));

  const tools = SIZES.map((s, k) => {
    const y = k * GAP, grp = mk("g", {}, g);
    const edge = mk("path", { class: "lo" }, grp), face = mk("path", { class: "sil" }, grp);
    // its fitted recess in the tray
    return { k, s, y, shape: outline(s), grp, edge, face, z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN };
  });

  function draw(t, z) {
    if (z === t.last) return;
    t.last = z;
    const w = (u, v, zz) => P(u + 4, t.y + v, zz);
    t.edge.setAttribute("d", poly(t.shape.map(([u, v]) => w(u, v, 0.4 + z))));
    t.face.setAttribute("d", poly(t.shape.map(([u, v]) => w(u, v, 0.4 + z + TK))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const t of tools) { draw(t, tval(t.z, now)); if (!tdone(t.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = tools.map((t) => P(LEN / 2, t.y, 1));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    // across the row the spanners lie along +y: the screen direction of y picks them
    mids.forEach((m, k) => { const dd = Math.hypot(m[0] - sx, m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    tools.forEach((t, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(t.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      t.face.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "spanner " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "wrenches",
  means: "A tray of six spanners in size order: the one under the pointer lifts out, and its neighbours rise a little.",
  rules: [1, 2, 5, 9],
  range: [0, 45, 90],
  tour: [[251, 122], [187, 154], [145, 175], null],
  mount,
});

clothesrack.code:
/**
 * Clothes rack: seven shirts on hangers along a rail on two stands, each a
 * flat shirt with sleeves and a collar notch under a wire hanger. The pointer
 * picks a shirt by where it hangs: it swings out toward the reader on its
 * hook, and the shirts beside it slide apart along the rail, staggered from
 * it. At rest one shirt is swung out a little, bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row (riffle), hanging.
 */
const {
  Cam, fillet, fit, facing, open, poly, prism, proj, rad, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 7, STEP = 13, RZ = 86, SW = 34, SWING = 32, PART = 7, FAV = 4;
const X1 = (N - 1) * STEP + 24;
// a shirt in its own plane: w across (centred), d down from the hook
const SHIRT = fillet([
  [-6, 10], [-3, 12], [3, 12], [6, 10], [16, 14], [20, 26], [14, 28], [12, 22], [12, 60], [-12, 60], [-12, 22], [-14, 28], [-20, 26], [-16, 14],
], [1, 2, 2, 1, 3, 2, 2, 1, 2, 2, 1, 2, 2, 3]);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-12, -14, 0], [X1 + 12, SW, 0], [X1 + 12, -14, 0], [-12, SW, 0], [-12, 0, RZ + 6], [X1 + 12, 0, RZ + 6], [X1, 36, RZ - 50]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // two stands and the rail
  for (const x of [-10, X1 + 6]) {
    const [fr, fi] = rings(x - 6, -14, x + 10, 14, 3, 1); put(solid(g), prism(P, front, fr, fi, 0, 3));
    const [pr, pi] = rings(x, -1.5, x + 3, 1.5, 1, 0.4); put(solid(g), prism(P, front, pr, pi, 3, RZ + 2));
  }
  const [rr, ri] = rings(-10, -1.4, X1 + 9, 1.4, 1.2, 0.5);
  const railEl = solid(g);
  put(railEl, prism(P, front, rr, ri, RZ, RZ + 2.4));

  const shirts = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    const back = mk("path", { class: "lo" }, grp), face = mk("path", { class: "sil" }, grp);
    const hanger = mk("path", { class: "nf" }, grp), placket = mk("path", { class: "nf lo" }, grp);
    shirts.push({ k, x: 12 + k * STEP, grp, back, face, hanger, placket, a: tween(k === FAV ? SWING * 0.45 : 0), dx: tween(0), last: "" });
  }
  g.appendChild(railEl.g);

  function draw(s, a, dx) {
    const key = a.toFixed(2) + "," + dx.toFixed(2);
    if (key === s.last) return;
    s.last = key;
    const ca = Math.cos(rad(a)), sa = Math.sin(rad(a)), x = s.x + dx;
    // the shirt hangs in the plane x = const and swings about the rail (the x axis) toward +y
    const w = (u, d, off = 0) => P(x + off, u * ca + d * sa, RZ - 4 - (d * ca - u * sa * 0));
    s.face.setAttribute("d", poly(SHIRT.map(([u, d]) => w(u, d))));
    s.back.setAttribute("d", poly(SHIRT.map(([u, d]) => w(u, d, -1))));
    s.hanger.setAttribute("d", open([P(x, 0, RZ + 3), P(x, 0, RZ + 1), w(-15, 12), w(15, 12), P(x, 0, RZ + 1)]));
    s.placket.setAttribute("d", seg(w(0, 13), w(0, 58)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const s of shirts) { draw(s, tval(s.a, now), tval(s.dx, now)); if (!tdone(s.a, now) || !tdone(s.dx, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = shirts.map((s) => P(s.x, 0, RZ - 34));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 12 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    shirts.forEach((s, k) => {
      const delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(s.a, a < 0 ? (k === FAV ? SWING * 0.45 : 0) : k === a ? SWING : 0, now, delay);
      tset(s.dx, a < 0 ? 0 : k < a ? -PART * Math.max(0, 1 - (a - k - 1) * 0.5) : k > a ? PART * Math.max(0, 1 - (k - a - 1) * 0.5) : 0, now, delay);
      s.face.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "shirt " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "clothesrack",
  means: "Seven shirts on a rail: the one under the pointer swings out toward you, and the shirts beside it slide apart.",
  rules: [1, 2, 5, 10],
  range: [0, 40, 80],
  tour: [[164, 123], [212, 147], [261, 172], null],
  mount,
});

cloches.code:
/**
 * Cloches: four domed covers on plates along a counter, each dome with a
 * knob, each plate holding a dish under it. The pointer picks a cloche by
 * where it stands: its dome lifts off the plate to show the dish, and the
 * domes beside it lift a little, staggered from it. At rest one dome is
 * raised, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 40, DR = 15, PR = 18, LIFT = 22, FAV = 1, CZ = 4;
const X1 = (N - 1) * STEP + 2 * PR;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.85);
  fit(C, [[-6, -6, 0], [X1 + 6, 2 * PR + 6, 0], [X1 + 6, -6, 0], [-6, 2 * PR + 6, 0], [PR, PR, CZ + DR + LIFT + 6], [X1 - PR, PR, CZ + DR + LIFT + 6]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-6, -6, X1 + 6, 2 * PR + 6, 6, 2);
  put(solid(g), prism(P, front, cr, ci, 0, CZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = PR + k * STEP, y = PR, grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, y, PR), disc(x, y, PR - 3), CZ, CZ + 1.6));
    // the dish: a low mound on the plate
    const mound = [];
    for (const [r, z] of [[9, 0], [7.5, 2.5], [5, 4.5], [2, 5.5]]) mound.push(...ringAt(P, disc(x + 1, y, r, 20), CZ + 1.6 + z));
    mk("path", { d: poly(hull(mound)), class: "nf" }, grp);
    const dome = mk("path", { class: "sil" }, grp), rim = mk("path", { class: "nf lo" }, grp), knob = mk("path", { class: "nf" }, grp);
    items.push({ k, x, y, grp, dome, rim, knob, z: tween(k === FAV ? LIFT * 0.75 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const base = CZ + 1.8 + lift, pts = [];
    for (let i = 0; i <= 6; i++) { const t = (i / 6) * (Math.PI / 2); pts.push(...ringAt(P, disc(it.x, it.y, DR * Math.cos(t), 28), base + DR * 0.9 * Math.sin(t))); }
    it.dome.setAttribute("d", poly(hull(pts)));
    it.rim.setAttribute("d", poly(ringAt(P, disc(it.x, it.y, DR, 40), base + 1.2)));
    const top = base + DR * 0.9;
    it.knob.setAttribute("d", poly(hull(ringAt(P, disc(it.x, it.y, 2.2, 16), top).concat(ringAt(P, disc(it.x, it.y, 2.2, 16), top + 3)))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, CZ + DR / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 30 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.75 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.dome.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "plate " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

